import log from 'loglevel';
import { Map } from 'immutable';
import { createStore, applyMiddleware, compose } from 'redux';
import { connectRouter, routerMiddleware } from 'connected-react-router/immutable';

import { createBrowserHistory } from 'history';

import createSagaMiddleware from 'redux-saga';
import multi from 'redux-multi';

import rootReducer from './reducers';
import rootSaga from './sagas';

import config from '../config';

// MUST BE ONLY ONE INSTANCE (for middleware and sync)
const history = createBrowserHistory(config.history);

export default function configureStore(initialState = Map()) {
    // Create middlewares
    const sagaMiddleware = createSagaMiddleware();
    const routingMiddleware = routerMiddleware(history);

    // Initialization of middlewares
    const middleware = applyMiddleware(multi, sagaMiddleware, routingMiddleware);

    // enhancer for production mode
    let enhancer = compose(middleware);

    // DevTools by config
    if (config.devTools) {
        // eslint-disable-next-line no-underscore-dangle
        if (window.__REDUX_DEVTOOLS_EXTENSION__) {
            // enhancer for development mode with DevTool extension
            enhancer = compose(
                middleware,
                // eslint-disable-next-line no-underscore-dangle
                window.__REDUX_DEVTOOLS_EXTENSION__(),
            );
        } else {
            // enhancer for development mode without DevTool extension
            log.warn("You haven't devTools extension in browser!");
        }
    }

    // Create store
    const store = createStore(connectRouter(history)(rootReducer), initialState, enhancer);
    // Run saga middleware with given root saga
    let sagaTask = sagaMiddleware.run(rootSaga);

    // Enable hot reload where available.
    if (import.meta.hot) {
        // Enable hot module replacement for reducers.
        import.meta.hot.accept('./reducers', (newModule) => {
            if (newModule) store.replaceReducer(connectRouter(history)(newModule.default));
        });

        // Enable hot module replacement for sagas.
        import.meta.hot.accept('./sagas', (newModule) => {
            if (!newModule) return;

            sagaTask.cancel();
            sagaTask.done.then(() => {
                sagaTask = sagaMiddleware.run(newModule.default);
            });
        });
    }

    return {
        store,
        history,
    };
}
